def receive(inputs): report, = inputs["child_reports"] assert set(report) == {field} assert [row["component"] for row in report[field]] == components assert report[field][0]["value"] == 1 assert report[field][1]["value"] is None received.append(report) assert "child_population_operations" in inputs["reference_evidence_parent"] source = store.get(args["source_ref"]) raw = store.get_artifact(source["artifact_ref"]) commit = {name: [] for name in store.reasoning_schema()["required"]} commit["source_subjects"] = [{"alias": "reported_subject", "reference_type": "assay", "source_ref": source["id"], "label": "source construct", "anchor": { "source_ref": source["id"], "artifact_ref": source["artifact_ref"], "start": 0, "end": len(raw), "quote": raw.decode("utf-8")}}] return {"selection": {"kind": "reason", "commit": commit}, "report_update": {}}
def controller(path, initial): value = FixtureController(str(path), initial, 2 if len(path) == 1 else 1) controllers.append(value) return value
provider = ScriptedProvider([commission, populate, receive]) scorer = ScientificFindingProgress(FindingProgressPolicy(1)) > summary = asyncio.run(run_workflow(store, ToolRegistry(store), provider=provider, run_dir=tmp_path / "run", controller_factory=controller, project_credit=scorer, initial_known_record_refs=[args["source_ref"]], episode_binding_factories=(partial(LiteratureEpisodes, rate_population=True, reference_parent_sources=[args["source_ref"]]),), binding_definitions={"credit": scorer.as_record()}))
